using System;using System.IO;using System.Drawing;using System.Reflection;using System.Windows.Forms;using System.Runtime.InteropServices;using System.Collections.Generic;using FleetLab;
class CheckFleetPointer {
 const BindingFlags F=BindingFlags.Instance|BindingFlags.Public|BindingFlags.NonPublic;
 [DllImport("user32.dll")]static extern IntPtr SendMessage(IntPtr h,int m,IntPtr w,IntPtr l);
 static object Field(object o,string name){return o.GetType().GetField(name,F).GetValue(o);}
 static object Prop(object o,string name){return o.GetType().GetProperty(name,F).GetValue(o,null);}
 static void Call(object o,string name,params object[] args){o.GetType().GetMethod(name,F).Invoke(o,args);}
 [STAThread]static int Main(string[] args){var rows=new List<string>();try{Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);using(var form=new MainForm(Path.GetFullPath(args[0]))){form.GetType().GetField("previewMode",F).SetValue(form,true);form.ShowInTaskbar=false;form.StartPosition=FormStartPosition.Manual;form.Location=new Point(-20000,-20000);((Audio)Field(form,"sound")).Enabled=false;((ClipStudy)Field(form,"clip")).SetSound(false);((ClipStudy)Field(form,"battleMovie")).SetSound(false);form.Show();Application.DoEvents();((TabControl)Field(form,"tabs")).SelectedIndex=4;object front=Field(form,"front"),solo=Field(form,"solo"),fleet=Field(form,"fleet");Call(front,"FinishReveal");Call(front,"Activate",0);Call(solo,"FinishReveal");Call(solo,"Activate",6);Call(solo,"Activate",10);Application.DoEvents();var canvas=(Control)Field(fleet,"Canvas");var box=(RectangleF)Prop(canvas,"Bounds4x3");var image=(Bitmap)Prop(fleet,"CurrentImage");rows.Add("Image="+image.Width+"x"+image.Height);int x=(int)(box.X+60*box.Width/image.Width),y=(int)(box.Y+445*box.Height/image.Height);IntPtr packed=new IntPtr(x|(y<<16));
 Action<string> log=delegate(string name){rows.Add(name+" capture="+canvas.Capture+" pressed="+Field(canvas,"pressed")+" button="+Field(canvas,"pressedButton")+" selected="+Prop(fleet,"SelectedShip")+" phase="+form.State.Phase);};canvas.MouseDown+=delegate{log("MouseDown");};canvas.MouseUp+=delegate{log("MouseUp");};canvas.MouseCaptureChanged+=delegate{log("CaptureChanged");};log("Before");SendMessage(canvas.Handle,0x201,new IntPtr(1),packed);log("After WM_LBUTTONDOWN");SendMessage(canvas.Handle,0x202,IntPtr.Zero,packed);Application.DoEvents();log("After WM_LBUTTONUP");bool started=form.State.Phase==Phase.PlayerTurn;rows.Add("Started="+started);form.Close();File.WriteAllLines(args[1],rows.ToArray());return started?0:1;}}catch(Exception e){rows.Add(e.ToString());File.WriteAllLines(args[1],rows.ToArray());return 2;}}
}
